-- À lancer après 20261003000000_annales.sql. Rejouable : le sujet est
-- remplacé s'il existe déjà.

insert into public.annales
  (matiere, annee, session, academie, filiere_libelle, duree_minutes, coefficient, enonce_mdx, corrige_mdx, questions)
values (
  $sujet$arabe$sujet$,
  2024,
  $sujet$normale$sujet$,
  $sujet$Béni Mellal-Khénifra$sujet$,
  $sujet$الشعب العلمية والتقنية - المترشحون الممدرسون$sujet$,
  120,
  2,
  $sujet$**إقرأ النص قراءة متانية، ثم أنجز الأنشطة الآتية:**

## النص

### التواصل اللغوي

إن التواصل عملية تتم في شكل علامات، أو رموز أو إشارات أو تلميحات أو إيماءات، أو غيرها. ولا يشك أي منّا في أن التواصل اللغوي، مهما تنوعت ميادينه، أو تفاوتت أدواره، أساسي في جميع مجالات الحياة، وأن أي فوضى تعتري هذه العملية، تتبعها صعوبة في فهم الرسالة، وفي كيفية أدائها. لقد لفت العلماء أنظار الباحثين والمسؤولين في شتى بقاع العالم إلى أهمية علم التواصل، ولاسيما بعد الثورة التواصلية الهائلة التي عرفتها بلدان المعمور. وشاهِدُنا على ذلك ما نراه من كثرة المؤتمرات، والندوات، والمنتديات، والمجلات التي تناقش قضايا هذا العلم.

ولابد لهذه العملية التواصلية من نسيج وثيق الترابط مع نظام لغوي دقيق، قوامه التعبير، وتبادل الآراء بين طرفي الحديث في مقام ما. وتمثل المشاركة اللغوية بين الطرفين أقصى درجات العملية الكلامية التي تبدأ بصوت وتنتهي برسالة، مرورا بالمواقف الاجتماعية والثقافية المصاحبة لهذه العملية. تلك المواقف التي يتبادل فيها الطرفان وجهات النظر فيما بينهما، ويصلان في نهاية الحديث إلى غايتهما. ولأن العملية الكلامية هي سمة إنسانية تختص بقدرات ومهارات تفتقر إليها باقي الكائنات الحية الأخرى، فإن هذه القدرات تتطلب توفر أصوات لغوية ونظام لغوي.

وتتأسس عملية التواصل على أربعة مقومات هي: المرسل، والمستقبل، والرسالة، ثم قناة التواصل؛ إذ ترتبط هذه المقومات ارتباطا وثيقا بعملية التواصل، مشكِّلة وظائف تؤول في نهاية المطاف إلى دور اللغة في المجتمع، وأهميتها بالنسبة إلى الفرد والجماعة. فاللغة أداة للتعبير عن الأفكار والأحاسيس التي تنتقل من المتحدث إلى المتلقي، وهي أداة معرفية لا يمكن التغاضي عنها؛ إذ يسأل المتحدث بها عن الجوانب المعرفية التي لا يعرفها، حتى يتزود بها لسد النقص في معلوماته. واللغة أيضا أداة لقياس درجة الاستجابة وإثارة أفكار المتلقي حين سماع الرسالة. تلك إذن أهم المقومات والأدوات التي تقوم عليها العملية التواصلية بين الأفراد والجماعات.

*سعد علي زاير وآخرون، الاتصال والتواصل التعليمي، دار الرضوان للنشر والتوزيع، عمان، الأردن، ط1، 2020م، 1441هـ، ص72 وما بعدها (بتصرف).*

## أولا: مكون النصوص (10 ن)

**1.** حدّد العلاقة بين عنوان النص وموضوعه. **(1 ن)**

**2.** حدّد القضية الأساس في النص. **(1 ن)**

**3.** اِشرح قول الكاتب: "العملية الكلامية، هي سمة إنسانية تختص بقدرات ومهارات تفتقر إليها باقي الكائنات الحية الأخرى". **(1 ن)**

**4.** تتوزع النصَّ حقولٌ دلالية، حدّد الحقل الدلالي المهيمن، ثم استخرج الألفاظ والعبارات الدالة عليه (أربعة ألفاظ/عبارات على الأقل). **(1.5 ن)**

| الحقل الدلالي المهيمن | الألفاظ والعبارات الدالة عليه |
|---|---|
| | |

**5.** بيّن أهمية اللغة ودورها في عملية التواصل بالنسبة إلى الفرد والمجتمع. **(1 ن)**

**6.** إستخرج من النص مثالين لأسلوب التأكيد، مع إبراز وظيفته في النص (المثال الأول، المثال الثاني، الوظيفة). **(1.5 ن)**

**7.** ركّب في فقرة موجزة قضايا النص، مبديا رأيك الشخصي في أهمية التواصل غير اللغوي لدى الإنسان. **(3 ن)**

## ثانيا: مكون علوم اللغة (4 ن)

**1.** إستخرج طباقا من النص، وحدد نوعه (الطباق، نوعه). **(2 ن)**

**2.** كوّن جملتين في موضوع النص، تتضمنان أسلوب الأمر بصيغتين مختلفتين (الجملة الأولى، الجملة الثانية). **(2 ن)**

## ثالثا: مكون التعبير والإنشاء (6 ن)

"قد تعترض العملية التواصلية مجموعة من المعيقات التي تحول دون تحقق الغايات المرجوة منها".

أُكتب موضوعا إنشائيا متكاملا توسع فيه هذه الفكرة، مسترشدا بما درسته في مهارة توسيع فكرة.$sujet$,
  $sujet$## عناصر الإجابة وسلم التنقيط

*تعد هذه العناصر للاستئناس، لذا تقبل كل إجابة مناسبة.*

### أولا: مكون النصوص (10 ن)

**1.** العلاقة بين عنوان النص وموضوعه هي علاقة ترابط /العنوان يختزل موضوع النص/ النص يوسع العنوان.. **(1 ن)**

**2.** القضية الأساس في النص هي: التواصل اللغوي: أهميته، ومقوماته، ودوره بالنسبة إلى الفرد والمجتمع.. **(1 ن)**

**3.** يؤكد الكاتب أن التواصل اللغوي عملية كلامية لا تتأتى إلا للإنسان، بينما تنعدم هذه السمة عند باقي الكائنات الأخرى، لأن الإنسان يختص بملكة التعبير باللغة عن أفكاره وأحاسيسه ورغباته بحسب ما يقتضيه السياق.. **(1 ن)**

**4.**  **(1.5 ن)**

| الحقل الدلالي المهيمن | الألفاظ والعبارات الدالة عليه |
|---|---|
| التواصل اللغوي (0.5ن) | التواصل اللغوي، الرسالة، اللغة، أصوات لغوية، نظام لغوي، عملية كلامية، المشاركة اللغوية، التعبير... (1ن) |

**5.** يبين المترشح أهمية اللغة ودورها في عملية التواصل بالنسبة إلى الفرد والمجتمع من خلال الإشارة إلى ما يأتي: التعبير عن المواقف الاجتماعية والثقافية، والأفكار والأحاسيس، وتبادل وجهات النظر، وتحصيل المعرفة، وإثارة أفكار المتلقي.. **(1 ن)**

**6.** من أمثلة أسلوب التأكيد في النص ما يأتي: (1ن) - إن التواصل عملية تتم في شكل علامات... - لقد لفت العلماء أنظار... - وأن أي فوضى تعتري هذا المبدأ... وظيفة الأسلوب: يؤدي هذا الأسلوب وظيفة حجاجية. يؤكد الكاتب من خلاله صحة كلامه وأفكاره.. (0.5ن) **(1.5 ن)**

**7.** تركيب قضايا النص في فقرة موجزة، وإبداء الرأي الشخصي في أهمية التواصل غير اللغوي عند الإنسان. - تركيب موجز لقضايا النص (1.5ن) - إبداء الرأي الشخصي (1.5ن) (وتقبل كل إجابة مناسبة) **(3 ن)**

### ثانيا: مكون علوم اللغة (4 ن)

**1.** الطباق الوارد في النص: الفرد ≠ الجماعة أو المرسل ≠ المستقبل (1ن) نوعه: طباق الإيجاب (1ن) (وتقبل كل إجابة مناسبة) **(2 ن)**

**2.** يكوّن المترشح جملتين في موضوع النص تتضمنان أسلوب الأمر بصيغتين مختلفتين من صيغ الأمر الأربع (1ن لكل جملة). (وتقبل كل إجابة مناسبة) **(2 ن)**

### ثالثا: مكون التعبير والإنشاء (6 ن)

يراعي المصحح في تقويم إنتاجات المترشحين ما يأتي:

- الالتزام بالمطلوب. (1ن)
- توظيف خصائص مهارة توسيع فكرة. (3ن)
- سلامة اللغة وتوظيف علامات الترقيم. (2ن)$sujet$,
